/**
 * Safety Manager
 *
 * Orchestrates multiple safety guards to provide comprehensive
 * content validation for the SAGE agentic system.
 */

import type {
  SafetyGuard,
  SafetyCheckResult,
  SafetyContext,
  SafetyConfig,
  SafetyIssue,
} from './types';

/**
 * Aggregated safety result
 */
export interface AggregatedSafetyResult extends SafetyCheckResult {
  /** Results from individual guards */
  guardResults: Record<string, SafetyCheckResult>;

  /** Whether any guard blocked the content */
  blocked: boolean;

  /** Guards that flagged issues */
  flaggedBy: string[];
}

/**
 * Create a safety manager
 */
export function createSafetyManager(config: SafetyConfig) {
  const guards = config.guards;
  const severityOrder = { low: 0, medium: 1, high: 2, critical: 3 };
  const blockSeverity = config.blockSeverity ?? 'high';

  return {
    /**
     * Check content against all guards
     */
    async check(content: string, context?: SafetyContext): Promise<AggregatedSafetyResult> {
      // Check bypass
      if (context && config.bypass?.(context)) {
        return {
          safe: true,
          issues: [],
          guardResults: {},
          blocked: false,
          flaggedBy: [],
        };
      }

      // Run all guards in parallel
      const results = await Promise.all(
        guards.map(async guard => {
          try {
            const result = await guard.check(content, context);
            return { guard: guard.name, result };
          } catch (error) {
            // Guard error - fail open but log
            console.error(`[SafetyManager] Guard "${guard.name}" failed:`, error);
            return {
              guard: guard.name,
              result: { safe: true, issues: [], confidence: 0 },
            };
          }
        })
      );

      // Aggregate results
      const guardResults: Record<string, SafetyCheckResult> = {};
      const allIssues: SafetyIssue[] = [];
      const flaggedBy: string[] = [];

      for (const { guard, result } of results) {
        guardResults[guard] = result;
        allIssues.push(...result.issues);

        if (!result.safe) {
          flaggedBy.push(guard);
        }
      }

      // Determine if blocked
      const blocked = allIssues.some(
        issue =>
          issue.action === 'block' ||
          severityOrder[issue.severity] >= severityOrder[blockSeverity]
      );

      // Get sanitized content if available
      let sanitized: string | undefined;
      if (config.sanitize) {
        for (const { guard, result } of results) {
          if (result.sanitized) {
            sanitized = result.sanitized;
            // Keep sanitizing through subsequent guards
            for (const g of guards) {
              if (g.name !== guard && g.sanitize) {
                sanitized = await g.sanitize(sanitized, context);
              }
            }
            break;
          }
        }
      }

      const aggregatedResult: AggregatedSafetyResult = {
        safe: allIssues.length === 0,
        issues: allIssues,
        sanitized,
        guardResults,
        blocked,
        flaggedBy,
        confidence: allIssues.length > 0
          ? Math.max(...results.map(r => r.result.confidence ?? 0))
          : 0,
      };

      // Call violation callback if issues found
      if (allIssues.length > 0 && config.onViolation && context) {
        config.onViolation(aggregatedResult, context);
      }

      return aggregatedResult;
    },

    /**
     * Sanitize content through all guards
     */
    async sanitize(content: string, context?: SafetyContext): Promise<string> {
      let result = content;

      for (const guard of guards) {
        if (guard.sanitize) {
          result = await guard.sanitize(result, context);
        }
      }

      return result;
    },

    /**
     * Check and block if unsafe (throws on block)
     */
    async enforce(content: string, context?: SafetyContext): Promise<string> {
      const result = await this.check(content, context);

      if (result.blocked) {
        const criticalIssue = result.issues.find(i => i.severity === 'critical');
        throw new SafetyViolationError(
          criticalIssue?.message ?? 'Content blocked by safety system',
          result
        );
      }

      // Return sanitized content if available, otherwise original
      return result.sanitized ?? content;
    },

    /**
     * Get guard by name
     */
    getGuard(name: string): SafetyGuard | undefined {
      return guards.find(g => g.name === name);
    },

    /**
     * Add a guard at runtime
     */
    addGuard(guard: SafetyGuard): void {
      guards.push(guard);
    },

    /**
     * Remove a guard at runtime
     */
    removeGuard(name: string): boolean {
      const index = guards.findIndex(g => g.name === name);
      if (index !== -1) {
        guards.splice(index, 1);
        return true;
      }
      return false;
    },
  };
}

/**
 * Safety violation error
 */
export class SafetyViolationError extends Error {
  public readonly result: AggregatedSafetyResult;

  constructor(message: string, result: AggregatedSafetyResult) {
    super(message);
    this.name = 'SafetyViolationError';
    this.result = result;
  }
}

/**
 * Create a safety manager with common defaults
 */
export function createDefaultSafetyManager(
  overrides?: Partial<SafetyConfig>
): ReturnType<typeof createSafetyManager> {
  // Import guards dynamically to avoid circular deps
  const { createInjectionGuard } = require('./guards/injection');
  const { createPIIGuard } = require('./guards/pii');
  const { createContentFilter } = require('./guards/content-filter');
  const { createToolSafetyGuard } = require('./guards/tool-safety');

  const config: SafetyConfig = {
    guards: [
      createInjectionGuard(),
      createPIIGuard(),
      createContentFilter(),
      createToolSafetyGuard(),
    ],
    defaultAction: 'warn',
    blockSeverity: 'high',
    sanitize: true,
    ...overrides,
  };

  return createSafetyManager(config);
}

/**
 * Create a minimal safety manager (fast, basic checks only)
 */
export function createMinimalSafetyManager(
  overrides?: Partial<SafetyConfig>
): ReturnType<typeof createSafetyManager> {
  const { createInjectionGuard } = require('./guards/injection');

  const config: SafetyConfig = {
    guards: [createInjectionGuard({ minSeverity: 'high' })],
    defaultAction: 'warn',
    blockSeverity: 'critical',
    sanitize: false,
    ...overrides,
  };

  return createSafetyManager(config);
}
