/**
 * Create a content filter guard
 */
export function createContentFilter(config?: ContentFilterConfig): SafetyGuard {
  const cfg = {
    useBuiltinRules: true,
    minSeverity: 'medium' as const,
    ...config,
  };

  // Build rule set
  let rules: ContentFilterRule[] = [];

  if (cfg.useBuiltinRules) {
    rules = [...BUILTIN_RULES];

    // Filter by enabled/disabled categories
    if (cfg.enableCategories) {
      rules = rules.filter(r => cfg.enableCategories!.includes(r.category));
    }
    if (cfg.disableCategories) {
      rules = rules.filter(r => !cfg.disableCategories!.includes(r.category));
    }
  }

  // Add custom rules
  if (cfg.rules) {
    rules = [...rules, ...cfg.rules];
  }

  const severityOrder = { low: 0, medium: 1, high: 2, critical: 3 };

  return {
    name: 'content_filter',
    description: 'Filters harmful and policy-violating content',

    async check(content: string, context?: SafetyContext): Promise<SafetyCheckResult> {
      const issues: SafetyIssue[] = [];

      for (const rule of rules) {
        // Skip if below minimum severity
        if (severityOrder[rule.severity] < severityOrder[cfg.minSeverity]) {
          continue;
        }

        for (const pattern of rule.patterns) {
          const regex = pattern instanceof RegExp
            ? pattern
            : new RegExp(
                rule.wordBoundary !== false ? `\\b${escapeRegex(pattern)}\\b` : escapeRegex(pattern),
                rule.caseSensitive ? 'g' : 'gi'
              );

          const match = content.match(regex);
          if (match) {
            // Check allowlist
            if (cfg.allowlist?.some(allow => allow.test(match[0]))) {
              continue;
            }

            issues.push({
              type: 'harmful_content',
              severity: rule.severity,
              message: `${rule.category.replace('_', ' ')}: ${rule.name}`,
              match: match[0],
              location: {
                start: content.indexOf(match[0]),
                end: content.indexOf(match[0]) + match[0].length,
              },
              action: rule.action ?? 'warn',
            });

            // Only report first match per rule
            break;
          }
        }
      }

      return {
        safe: issues.length === 0,
        issues,
        confidence: issues.length > 0 ? 0.8 : 0,
      };
    },
  };
}

/**
 * Escape special regex characters
 */
function escapeRegex(str: string): string {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Create a simple keyword blocklist filter
 */
export function createBlocklistFilter(
  blocklist: string[],
  options?: {
    severity?: 'low' | 'medium' | 'high' | 'critical';
    category?: ContentCategory;
    caseSensitive?: boolean;
    wordBoundary?: boolean;
  }
): SafetyGuard {
  const {
    severity = 'medium',
    category = 'custom',
    caseSensitive = false,
    wordBoundary = true,
  } = options ?? {};

  const patterns = blocklist.map(word => {
    const escaped = escapeRegex(word);
    const pattern = wordBoundary ? `\\b${escaped}\\b` : escaped;
    return new RegExp(pattern, caseSensitive ? 'g' : 'gi');
  });

  return {
    name: 'blocklist',
    description: 'Custom keyword blocklist filter',

    async check(content: string): Promise<SafetyCheckResult> {
      const issues: SafetyIssue[] = [];

      for (let i = 0; i < patterns.length; i++) {
        const match = content.match(patterns[i]);
        if (match) {
          issues.push({
            type: 'harmful_content',
            severity,
            message: `Blocked keyword: ${blocklist[i]}`,
            match: match[0],
            action: 'block',
          });
        }
      }

      return {
        safe: issues.length === 0,
        issues,
      };
    },
  };
}
