/**
 * Tool Safety Guard
 *
 * Validates tool usage for safety, preventing dangerous operations.
 */

import type { SafetyGuard, SafetyCheckResult, SafetyContext, SafetyIssue, ToolSafetyPolicy } from '../types';

/**
 * Tool safety configuration
 */
export interface ToolSafetyConfig {
  /** Tool-specific policies */
  policies?: ToolSafetyPolicy[];

  /** Default policy for unlisted tools */
  defaultPolicy?: 'allow' | 'warn' | 'block';

  /** Dangerous patterns to block in any tool */
  dangerousPatterns?: Array<{
    pattern: RegExp;
    description: string;
    severity: 'medium' | 'high' | 'critical';
  }>;

  /** Maximum argument size in bytes */
  maxArgumentSize?: number;

  /** Allowed file extensions for file operations */
  allowedFileExtensions?: string[];

  /** Blocked file paths */
  blockedPaths?: RegExp[];
}

/**
 * Default dangerous patterns
 */
const DEFAULT_DANGEROUS_PATTERNS: Array<{
  pattern: RegExp;
  description: string;
  severity: 'medium' | 'high' | 'critical';
}> = [
  // Command injection
  {
    pattern: /[;&|`$(){}[\]<>]/,
    description: 'Potential command injection characters',
    severity: 'high',
  },
  {
    pattern: /\b(rm\s+-rf|sudo|chmod\s+777|eval|exec)\b/i,
    description: 'Dangerous shell command',
    severity: 'critical',
  },
  
  // Path traversal
  {
    pattern: /\.\.[\/\\]/,
    description: 'Path traversal attempt',
    severity: 'high',
  },
  
  // SQL injection indicators
  {
    pattern: /('|")\s*(OR|AND)\s*('|"|\d)/i,
    description: 'Potential SQL injection',
    severity: 'high',
  },
  {
    pattern: /;\s*(DROP|DELETE|UPDATE|INSERT|TRUNCATE)\s/i,
    description: 'SQL injection - destructive command',
    severity: 'critical',
  },
  
  // Sensitive paths
  {
    pattern: /\/(etc\/passwd|etc\/shadow|\.ssh|\.env|\.git|node_modules)/i,
    description: 'Access to sensitive system path',
    severity: 'high',
  },
  
  // Network operations
  {
    pattern: /\b(0\.0\.0\.0|127\.0\.0\.1|localhost):\d+/i,
    description: 'Local network access',
    severity: 'medium',
  },
];

/**
 * Default blocked paths
 */
const DEFAULT_BLOCKED_PATHS: RegExp[] = [
  /^\/etc\//,
  /^\/var\/log\//,
  /^\/root\//,
  /^\/home\/[^/]+\/\.(ssh|gnupg|config)/,
  /\.env(\.|$)/i,
  /\.(pem|key|crt|p12|pfx)$/i,
  /node_modules/,
  /\.git\//,
];

/**
 * Default allowed file extensions
 */
const DEFAULT_ALLOWED_EXTENSIONS: string[] = [
  '.txt', '.md', '.json', '.yaml', '.yml', '.xml', '.csv',
  '.ts', '.js', '.tsx', '.jsx', '.py', '.rb', '.go', '.rs',
  '.html', '.css', '.scss', '.less',
  '.sh', '.bash', '.zsh',
  '.sql', '.graphql',
  '.toml', '.ini', '.conf',
];

/**
 * Create a tool safety guard
 */
export function createToolSafetyGuard(config?: ToolSafetyConfig): SafetyGuard {
  const cfg = {
    defaultPolicy: 'warn' as const,
    dangerousPatterns: DEFAULT_DANGEROUS_PATTERNS,
    maxArgumentSize: 100000, // 100KB
    blockedPaths: DEFAULT_BLOCKED_PATHS,
    allowedFileExtensions: DEFAULT_ALLOWED_EXTENSIONS,
    ...config,
  };

  return {
    name: 'tool_safety',
    description: 'Validates tool arguments for safety',

    async check(content: string, context?: SafetyContext): Promise<SafetyCheckResult> {
      const issues: SafetyIssue[] = [];
      const toolName = context?.toolName;
      const toolArgs = context?.toolArgs;

      // Check tool-specific policy
      if (toolName && cfg.policies) {
        const policy = cfg.policies.find(p => {
          if (typeof p.tool === 'string') {
            return p.tool === toolName;
          }
          return p.tool.test(toolName);
        });

        if (policy?.customCheck && toolArgs) {
          const customResult = policy.customCheck(toolArgs, context!);
          issues.push(...customResult.issues);
        }
      }

      // Check argument size
      if (content.length > cfg.maxArgumentSize) {
        issues.push({
          type: 'dangerous_tool_use',
          severity: 'medium',
          message: `Argument size (${content.length}) exceeds limit (${cfg.maxArgumentSize})`,
          action: 'warn',
        });
      }

      // Check dangerous patterns
      for (const { pattern, description, severity } of cfg.dangerousPatterns) {
        const match = content.match(pattern);
        if (match) {
          issues.push({
            type: 'dangerous_tool_use',
            severity,
            message: description,
            match: match[0],
            action: severity === 'critical' ? 'block' : 'warn',
          });
        }
      }

      // Check for blocked paths in content
      for (const blockedPath of cfg.blockedPaths) {
        if (blockedPath.test(content)) {
          issues.push({
            type: 'dangerous_tool_use',
            severity: 'high',
            message: 'Access to blocked path',
            match: content.match(blockedPath)?.[0],
            action: 'block',
          });
        }
      }

      // Check file extension if it looks like a file path
      const filePathMatch = content.match(/[a-zA-Z0-9_-]+\.[a-zA-Z0-9]+/g);
      if (filePathMatch && cfg.allowedFileExtensions) {
        for (const match of filePathMatch) {
          const ext = '.' + match.split('.').pop()!.toLowerCase();
          if (!cfg.allowedFileExtensions.includes(ext)) {
            issues.push({
              type: 'dangerous_tool_use',
              severity: 'medium',
              message: `File extension not in allowlist: ${ext}`,
              match,
              action: 'warn',
            });
          }
        }
      }

      return {
        safe: issues.length === 0,
        issues,
        confidence: issues.length > 0 ? 0.85 : 0,
      };
    },
  };
}

/**
 * Validate specific tool argument types
 */
export const ToolArgValidators = {
  /**
   * Validate a file path
   */
  filePath(path: string, config?: { allowedExtensions?: string[]; blockedPaths?: RegExp[] }): SafetyIssue[] {
    const issues: SafetyIssue[] = [];
    const blocked = config?.blockedPaths ?? DEFAULT_BLOCKED_PATHS;
    const allowed = config?.allowedExtensions ?? DEFAULT_ALLOWED_EXTENSIONS;

    // Check blocked paths
    for (const pattern of blocked) {
      if (pattern.test(path)) {
        issues.push({
          type: 'dangerous_tool_use',
          severity: 'high',
          message: 'Access to blocked path',
          match: path,
          action: 'block',
        });
      }
    }

    // Check path traversal
    if (/\.\.[\\/]/.test(path)) {
      issues.push({
        type: 'dangerous_tool_use',
        severity: 'high',
        message: 'Path traversal detected',
        match: path,
        action: 'block',
      });
    }

    // Check extension
    const ext = path.match(/\.[a-zA-Z0-9]+$/)?.[0]?.toLowerCase();
    if (ext && !allowed.includes(ext)) {
      issues.push({
        type: 'dangerous_tool_use',
        severity: 'medium',
        message: `File extension not allowed: ${ext}`,
        match: path,
        action: 'warn',
      });
    }

    return issues;
  },

  /**
   * Validate a URL
   */
  url(url: string): SafetyIssue[] {
    const issues: SafetyIssue[] = [];

    try {
      const parsed = new URL(url);

      // Block local addresses
      if (['localhost', '127.0.0.1', '0.0.0.0', '::1'].includes(parsed.hostname)) {
        issues.push({
          type: 'dangerous_tool_use',
          severity: 'high',
          message: 'Local network access not allowed',
          match: url,
          action: 'block',
        });
      }

      // Block private IPs
      if (/^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.)/.test(parsed.hostname)) {
        issues.push({
          type: 'dangerous_tool_use',
          severity: 'high',
          message: 'Private network access not allowed',
          match: url,
          action: 'block',
        });
      }

      // Block file:// protocol
      if (parsed.protocol === 'file:') {
        issues.push({
          type: 'dangerous_tool_use',
          severity: 'critical',
          message: 'File protocol not allowed',
          match: url,
          action: 'block',
        });
      }
    } catch {
      issues.push({
        type: 'dangerous_tool_use',
        severity: 'medium',
        message: 'Invalid URL format',
        match: url,
        action: 'warn',
      });
    }

    return issues;
  },

  /**
   * Validate shell command
   */
  shellCommand(command: string): SafetyIssue[] {
    const issues: SafetyIssue[] = [];

    // Block dangerous commands
    const dangerousCommands = [
      /\brm\s+(-rf?|--recursive)?\s*\//i,
      /\bsudo\b/i,
      /\bchmod\s+[0-7]*7[0-7]*\b/i,
      /\b(wget|curl)\s+.*\|\s*(bash|sh)\b/i,
      /\beval\s+/i,
      /\b(mkfs|dd\s+if=)/i,
    ];

    for (const pattern of dangerousCommands) {
      if (pattern.test(command)) {
        issues.push({
          type: 'dangerous_tool_use',
          severity: 'critical',
          message: 'Dangerous shell command detected',
          match: command.match(pattern)?.[0],
          action: 'block',
        });
      }
    }

    // Check for command injection
    if (/[;&|`$()]/.test(command)) {
      issues.push({
        type: 'dangerous_tool_use',
        severity: 'high',
        message: 'Command injection characters detected',
        match: command,
        action: 'warn',
      });
    }

    return issues;
  },
};
